-- ===== 0017_checkins.sql =====
-- Phase 1c, check-ins: the photo post of a workout, the posts a person hid from their feed, the
-- read-only app settings, and the private bucket that keeps the photos.

-- Tables ----------------------------------------------------------------------------------------

create table public.checkins (
  id           uuid primary key,                       -- made on the device
  user_id      uuid not null references auth.users on delete cascade default auth.uid(),
  day          date not null,
  activity     text not null check (activity in
                 ('strength','run','bike','swim','walk','sport','class','other')),
  routine_id   text check (char_length(routine_id) <= 64),
  routine_name text check (char_length(routine_name) <= 60),
  title        text not null check (char_length(btrim(title)) between 1 and 60),
  caption      text check (char_length(caption) <= 500),
  note         text check (char_length(note) <= 500),  -- private: never leaves for another account
  duration_min smallint check (duration_min between 1 and 600),
  visibility   text not null check (visibility in ('friends','private')),
  photo_path   text not null check (photo_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|webp)$'),
  detail       jsonb check (detail is null or octet_length(detail::text) <= 16384),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  -- The photo lives in the owner's folder and is named after the check-in, so a path names one post.
  constraint checkins_photo_path_own check (photo_path in (
    user_id::text || '/' || id::text || '.jpg', user_id::text || '/' || id::text || '.webp'))
);
create index checkins_user_day on public.checkins (user_id, day);
create index checkins_feed on public.checkins (created_at desc, id);

create table public.hidden_checkins (
  user_id    uuid not null references auth.users on delete cascade default auth.uid(),
  checkin_id uuid not null references public.checkins on delete cascade,
  primary key (user_id, checkin_id)
);
create index hidden_checkins_checkin on public.hidden_checkins (checkin_id);

-- Settings the server writes and every signed-in client may read (the phase cutover date, ...).
create table public.app_settings (
  key   text primary key,
  value jsonb
);

-- Visibility ------------------------------------------------------------------------------------
-- Who may see a post: its owner, or a friend when the post is for friends. Unfriending cuts access
-- at once. The Storage policies run as the client and call these, hence the grant to authenticated.

create or replace function public.can_see_checkin(p_checkin uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select c.user_id = auth.uid()
        or (c.visibility = 'friends' and c.user_id in (select public.friend_ids(auth.uid())))
      from public.checkins c
     where c.id = p_checkin and auth.uid() is not null), false)
$$;

-- The same question for a Storage path. Only the exact <owner>/<checkin>.(jpg|webp) shape is read;
-- the check-in must exist with that id, that owner and that very path. Anything else is false.
create or replace function public.can_see_checkin_path(p_path text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare
  v_parts text[];
  v_id    uuid;
begin
  v_parts := regexp_match(coalesce(p_path, ''),
    '^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/'
    || '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.(jpg|webp)$');
  if v_parts is null then
    return false;
  end if;
  select c.id into v_id from public.checkins c
   where c.id = v_parts[2]::uuid and c.user_id = v_parts[1]::uuid and c.photo_path = p_path;
  if v_id is null then
    return false;
  end if;
  return public.can_see_checkin(v_id);
end $$;

revoke all on function public.can_see_checkin(uuid), public.can_see_checkin_path(text)
  from public, anon;
grant execute on function public.can_see_checkin(uuid), public.can_see_checkin_path(text)
  to authenticated;

-- Access ----------------------------------------------------------------------------------------

alter table public.checkins enable row level security;
alter table public.hidden_checkins enable row level security;
alter table public.app_settings enable row level security;

revoke all on public.checkins, public.hidden_checkins, public.app_settings from anon;
revoke truncate on public.checkins from authenticated;
revoke update, truncate on public.hidden_checkins from authenticated;
revoke insert, update, delete, truncate on public.app_settings from authenticated;

-- Friends read posts only through security definer functions, never this table.
create policy checkins_select_own on public.checkins
  for select to authenticated using (user_id = auth.uid());
create policy checkins_insert_own on public.checkins
  for insert to authenticated with check (user_id = auth.uid());
create policy checkins_update_own on public.checkins
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy checkins_delete_own on public.checkins
  for delete to authenticated using (user_id = auth.uid());

create policy hidden_checkins_select_own on public.hidden_checkins
  for select to authenticated using (user_id = auth.uid());
create policy hidden_checkins_insert_own on public.hidden_checkins
  for insert to authenticated with check (user_id = auth.uid() and public.can_see_checkin(checkin_id));
create policy hidden_checkins_delete_own on public.hidden_checkins
  for delete to authenticated using (user_id = auth.uid());

create policy app_settings_select on public.app_settings
  for select to authenticated using (true);

-- Guard -----------------------------------------------------------------------------------------
-- Security invoker: the rules apply only to client roles. Security definer functions and the
-- cascade from auth.users run as the owner and pass untouched. Deleting is allowed at any time.

create function public.checkins_guard() returns trigger
language plpgsql security invoker set search_path = public as $$
declare
  v_today date;
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_today := public.my_local_today();
    if new.day not in (v_today - 1, v_today) then
      raise exception 'day_closed' using errcode = 'P0001';
    end if;
    if (select count(*) from public.checkins
         where user_id = new.user_id and day = new.day and id <> new.id) >= 10 then
      raise exception 'too_many_checkins' using errcode = 'P0001';
    end if;
    -- A post made offline keeps its earlier time; none is dated in the future to stay on top.
    new.created_at := least(coalesce(new.created_at, now()), now());
  else
    if new.id <> old.id or new.user_id <> old.user_id or new.day <> old.day
       or new.activity <> old.activity or new.photo_path <> old.photo_path then
      raise exception 'item_immutable' using errcode = 'P0001';
    end if;
    new.created_at := old.created_at;
  end if;

  new.updated_at := least(new.updated_at, now());
  if tg_op = 'UPDATE' and new.updated_at < old.updated_at then
    return null;
  end if;
  return new;
end $$;

create trigger checkins_guard before insert or update on public.checkins
  for each row execute function public.checkins_guard();

revoke all on function public.checkins_guard() from public, anon, authenticated;

-- Storage ---------------------------------------------------------------------------------------
-- Private bucket for the photos: JPEG or WebP up to 600 KB, read through signed links only.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('checkins', 'checkins', false, 614400, array['image/jpeg', 'image/webp'])
on conflict (id) do update set
  name = excluded.name,
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists checkins_photos_insert_own on storage.objects;
drop policy if exists checkins_photos_delete_own on storage.objects;
drop policy if exists checkins_photos_select on storage.objects;

-- Upload only into the own folder, as <checkin_id>.jpg or .webp.
create policy checkins_photos_insert_own on storage.objects
  for insert to authenticated with check (
    bucket_id = 'checkins'
    and (storage.foldername(name))[1] = auth.uid()::text
    and name ~ ('^' || auth.uid()::text
                || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|webp)$'));

create policy checkins_photos_delete_own on storage.objects
  for delete to authenticated using (
    bucket_id = 'checkins' and (storage.foldername(name))[1] = auth.uid()::text);

-- The owner always reads their own folder (a photo sent before its post, or left behind by a failed
-- post, can still be removed); anyone else only the photo of a post they may see.
create policy checkins_photos_select on storage.objects
  for select to authenticated using (
    bucket_id = 'checkins'
    and ((storage.foldername(name))[1] = auth.uid()::text or public.can_see_checkin_path(name)));

-- ===== 0018_checkin_social.sql =====
-- Phase 1c, the social side of check-ins: reactions, comments, the in-app notices they raise (plus
-- challenge invites), and get_checkin, the one way another account reads a post. The private note
-- and the workout detail never leave for another account.

-- Tables ----------------------------------------------------------------------------------------

create table public.checkin_reactions (
  checkin_id uuid not null references public.checkins on delete cascade,
  user_id    uuid not null references auth.users on delete cascade default auth.uid(),
  emoji      text not null check (octet_length(emoji) between 1 and 16),
  created_at timestamptz not null default now(),
  primary key (checkin_id, user_id, emoji)
);
create index checkin_reactions_user on public.checkin_reactions (user_id);

create table public.checkin_comments (
  id         bigint generated always as identity primary key,
  checkin_id uuid not null references public.checkins on delete cascade,
  user_id    uuid not null references auth.users on delete cascade default auth.uid(),
  body       text not null check (char_length(btrim(body)) between 1 and 500),
  created_at timestamptz not null default now()
);
create index checkin_comments_checkin on public.checkin_comments (checkin_id, id);
create index checkin_comments_user on public.checkin_comments (user_id);

create table public.social_notices (
  id           bigint generated always as identity primary key,
  user_id      uuid not null references auth.users on delete cascade,   -- who receives it
  actor_id     uuid not null references auth.users on delete cascade,
  kind         text not null check (kind in ('reaction', 'comment', 'challenge_invite')),
  checkin_id   uuid references public.checkins on delete cascade,
  challenge_id uuid references public.challenges on delete cascade,
  created_at   timestamptz not null default now(),
  read_at      timestamptz
);
create index social_notices_user on public.social_notices (user_id, id desc);
create index social_notices_unread on public.social_notices (user_id) where read_at is null;
create index social_notices_actor on public.social_notices (actor_id);
create index social_notices_checkin on public.social_notices (checkin_id);
create index social_notices_challenge on public.social_notices (challenge_id);

-- Access ----------------------------------------------------------------------------------------
-- Writes go in only on a post the person may see. Reading other people's reactions and comments is
-- done through get_checkin; the tables show a person only their own rows (and, for comments, the
-- ones on their own posts), which is what deleting needs.

alter table public.checkin_reactions enable row level security;
alter table public.checkin_comments enable row level security;
alter table public.social_notices enable row level security;

revoke all on public.checkin_reactions, public.checkin_comments, public.social_notices from anon;
revoke update, truncate on public.checkin_reactions, public.checkin_comments from authenticated;
revoke insert, update, delete, truncate on public.social_notices from authenticated;
grant update (read_at) on public.social_notices to authenticated;

create policy checkin_reactions_select_own on public.checkin_reactions
  for select to authenticated using (user_id = auth.uid());
create policy checkin_reactions_insert_visible on public.checkin_reactions
  for insert to authenticated with check (user_id = auth.uid() and public.can_see_checkin(checkin_id));
create policy checkin_reactions_delete_own on public.checkin_reactions
  for delete to authenticated using (user_id = auth.uid());

create policy checkin_comments_select on public.checkin_comments
  for select to authenticated using (
    user_id = auth.uid()
    or exists (select 1 from public.checkins c where c.id = checkin_id and c.user_id = auth.uid()));
create policy checkin_comments_insert_visible on public.checkin_comments
  for insert to authenticated with check (user_id = auth.uid() and public.can_see_checkin(checkin_id));
-- The author, or the owner of the post.
create policy checkin_comments_delete on public.checkin_comments
  for delete to authenticated using (
    user_id = auth.uid()
    or exists (select 1 from public.checkins c where c.id = checkin_id and c.user_id = auth.uid()));

create policy social_notices_select_own on public.social_notices
  for select to authenticated using (user_id = auth.uid());
create policy social_notices_update_own on public.social_notices
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Guards ----------------------------------------------------------------------------------------
-- Up to 10 different emojis per person on one post. The lock keeps two inserts at once from both
-- passing the count. The times are the server's, whatever a direct insert sends.

create function public.checkin_reactions_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform pg_advisory_xact_lock(
    hashtextextended('checkin-react:' || new.checkin_id::text || ':' || new.user_id::text, 0));
  if (select count(*) from public.checkin_reactions
       where checkin_id = new.checkin_id and user_id = new.user_id and emoji <> new.emoji) >= 10 then
    raise exception 'too_many_reactions' using errcode = 'P0001';
  end if;
  new.created_at := now();
  return new;
end $$;

create trigger checkin_reactions_guard before insert on public.checkin_reactions
  for each row execute function public.checkin_reactions_guard();

create function public.checkin_comments_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.body := btrim(new.body);
  new.created_at := now();
  return new;
end $$;

create trigger checkin_comments_guard before insert on public.checkin_comments
  for each row execute function public.checkin_comments_guard();

-- Notices ---------------------------------------------------------------------------------------
-- One notice per reaction or comment that lands on someone else's post, and one per challenge
-- invite. Never for oneself. Removing the reaction or comment leaves the notice; deleting the post
-- or the challenge takes it away.

create function public.notify_checkin_social() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_owner uuid;
begin
  select user_id into v_owner from public.checkins where id = new.checkin_id;
  if v_owner is not null and v_owner <> new.user_id then
    insert into public.social_notices (user_id, actor_id, kind, checkin_id)
    values (v_owner, new.user_id,
            case when tg_table_name = 'checkin_reactions' then 'reaction' else 'comment' end,
            new.checkin_id);
  end if;
  return null;
end $$;

create trigger checkin_reactions_notify after insert on public.checkin_reactions
  for each row execute function public.notify_checkin_social();
create trigger checkin_comments_notify after insert on public.checkin_comments
  for each row execute function public.notify_checkin_social();

-- create_challenge adds the invited friends as members with invited_by set and joined_at null
-- (the creator joins at once, with no inviter). That pending row is the invite.
create function public.notify_challenge_invite() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.joined_at is null and new.invited_by is not null and new.invited_by <> new.user_id then
    insert into public.social_notices (user_id, actor_id, kind, challenge_id)
    values (new.user_id, new.invited_by, 'challenge_invite', new.challenge_id);
  end if;
  return null;
end $$;

create trigger challenge_members_notify after insert on public.challenge_members
  for each row execute function public.notify_challenge_invite();

revoke all on function public.checkin_reactions_guard(), public.checkin_comments_guard(),
  public.notify_checkin_social(), public.notify_challenge_invite() from public, anon, authenticated;

-- RPCs ------------------------------------------------------------------------------------------
-- A post the caller may not see answers not_found, the same as one that does not exist.

create function public.react_checkin(p_id uuid, p_emoji text, p_on boolean) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if p_emoji is null or octet_length(p_emoji) not between 1 and 16 then
    raise exception 'invalid_emoji' using errcode = 'P0001';
  end if;
  if not coalesce(p_on, false) then
    -- Taking one's own reaction back works even after losing sight of the post.
    delete from public.checkin_reactions where checkin_id = p_id and user_id = v_me and emoji = p_emoji;
    return;
  end if;
  if not public.can_see_checkin(p_id) then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  insert into public.checkin_reactions (checkin_id, user_id, emoji)
  values (p_id, v_me, p_emoji)
  on conflict do nothing;
end $$;

create function public.comment_checkin(p_id uuid, p_body text) returns bigint
language plpgsql security definer set search_path = public as $$
declare
  v_me   uuid := auth.uid();
  v_body text := btrim(coalesce(p_body, ''));
  v_id   bigint;
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if char_length(v_body) not between 1 and 500 then
    raise exception 'invalid_comment' using errcode = 'P0001';
  end if;
  if not public.can_see_checkin(p_id) then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  insert into public.checkin_comments (checkin_id, user_id, body)
  values (p_id, v_me, v_body)
  returning id into v_id;
  return v_id;
end $$;

-- The author or the owner of the post; for anyone else the comment does not exist.
create function public.delete_comment(p_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  delete from public.checkin_comments m
   where m.id = p_id
     and (m.user_id = v_me
          or exists (select 1 from public.checkins c where c.id = m.checkin_id and c.user_id = v_me));
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
end $$;

-- One post with its reactions (grouped by emoji, with who reacted) and comments (oldest first).
-- note and detail are added only when the caller owns the post.
create function public.get_checkin(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_me  uuid := auth.uid();
  v_c   public.checkins%rowtype;
  v_out jsonb;
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if not public.can_see_checkin(p_id) then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  select * into v_c from public.checkins where id = p_id;

  v_out := jsonb_build_object(
    'id', v_c.id,
    'user', (select jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url)
               from public.profiles p where p.id = v_c.user_id),
    'day', v_c.day,
    'activity', v_c.activity,
    'routine_name', v_c.routine_name,
    'title', v_c.title,
    'caption', v_c.caption,
    'duration_min', v_c.duration_min,
    'visibility', v_c.visibility,
    -- can_see_checkin passed, so the caller may see the photo.
    'photo_path', v_c.photo_path,
    'created_at', v_c.created_at,
    'reactions', coalesce((
      select jsonb_agg(jsonb_build_object('emoji', g.emoji, 'count', g.n, 'mine', g.mine, 'users', g.users)
                       order by g.n desc, g.first_at, g.emoji)
        from (select r.emoji, count(*)::int as n, bool_or(r.user_id = v_me) as mine,
                     min(r.created_at) as first_at,
                     jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url)
                               order by r.created_at, r.user_id) as users
                from public.checkin_reactions r
                join public.profiles p on p.id = r.user_id
               where r.checkin_id = p_id
               group by r.emoji) g), '[]'::jsonb),
    'comments', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', m.id,
               'user', jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url),
               'body', m.body,
               'created_at', m.created_at,
               'can_delete', m.user_id = v_me or v_c.user_id = v_me)
             order by m.id)
        from public.checkin_comments m
        join public.profiles p on p.id = m.user_id
       where m.checkin_id = p_id), '[]'::jsonb));

  if v_c.user_id = v_me then
    v_out := v_out || jsonb_build_object('note', v_c.note, 'detail', v_c.detail);
  end if;
  return v_out;
end $$;

-- The caller's notices, newest first, and how many are unread in all.
create function public.get_notices(p_limit int default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  return jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', n.id,
               'kind', n.kind,
               'actor', jsonb_build_object('id', a.id, 'name', a.display_name, 'avatar_url', a.avatar_url),
               'checkin_id', n.checkin_id,
               'checkin_title', c.title,
               'challenge_id', n.challenge_id,
               'challenge_title', h.title,
               'created_at', n.created_at,
               'read', n.read_at is not null)
             order by n.id desc)
        from (select * from public.social_notices
               where user_id = v_me
               order by id desc
               limit greatest(1, least(coalesce(p_limit, 30), 100))) n
        left join public.profiles a on a.id = n.actor_id
        left join public.checkins c on c.id = n.checkin_id
        left join public.challenges h on h.id = n.challenge_id), '[]'::jsonb),
    'unread', (select count(*)::int from public.social_notices where user_id = v_me and read_at is null));
end $$;

-- Marks the caller's notices up to an id (the newest one the list showed) as read.
create function public.mark_notices_read(p_upto bigint) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  update public.social_notices
     set read_at = now()
   where user_id = v_me and id <= p_upto and read_at is null;
end $$;

revoke all on function public.react_checkin(uuid, text, boolean), public.comment_checkin(uuid, text),
  public.delete_comment(bigint), public.get_checkin(uuid), public.get_notices(int),
  public.mark_notices_read(bigint) from public, anon;
grant execute on function public.react_checkin(uuid, text, boolean), public.comment_checkin(uuid, text),
  public.delete_comment(bigint), public.get_checkin(uuid), public.get_notices(int),
  public.mark_notices_read(bigint) to authenticated;

-- ===== 0019_training_days.sql =====
-- Phase 1c, training days: check-ins pay the strength pillar (shown as "Treino"). A day closes at
-- the start of D+2 local into training_days and its server-only events pay XP (spec 5.1, 5.2).
-- From the cutover date on (app_settings.training_checkin_since, written below), workout_completed
-- no longer pays a day; earlier days keep what they paid and count as legacy training days.
-- Bodies of award_xp (0010), close_weeks (0002), achievement_stats (0011), challenge_progress
-- (0015), progress_card, my_progress_extras and get_my_progress (0012) are copied with only the
-- training parts changed; no signature changes.

-- Cutover date (decision 4) -------------------------------------------------------------------------
-- The day this migration runs. Days before it are legacy: their workout_completed already paid.

insert into public.app_settings (key, value)
values ('training_checkin_since', to_jsonb(current_date))
on conflict (key) do nothing;

-- Without the setting every day is a check-in day.
create function public.training_checkin_since() returns date
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select (value #>> '{}')::date from public.app_settings where key = 'training_checkin_since'),
    date '0001-01-01')
$$;

revoke all on function public.training_checkin_since() from public, anon, authenticated;

-- Closed days ---------------------------------------------------------------------------------------
--   checked   a check-in that day (a legacy day counts as one)
--   detailed  a check-in with workout detail (detail.entries not empty)
--   legacy    before the cutover with a workout_completed: counts for streak, challenges and
--             metrics, never pays training XP

create table public.training_days (
  user_id   uuid not null references auth.users on delete cascade,
  day       date not null,
  checked   boolean not null,
  detailed  boolean not null,
  legacy    boolean not null default false,
  closed_at timestamptz not null default now(),
  primary key (user_id, day)
);

alter table public.training_days enable row level security;
create policy training_days_select_own on public.training_days
  for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete, truncate on public.training_days from anon, authenticated;
revoke select on public.training_days from anon;

insert into public.event_kinds (pillar, kind, server_only) values
  ('strength', 'training_day', true),
  ('strength', 'training_detailed', true);

-- Weekly streak --------------------------------------------------------------------------------------
-- 0002's, with two changes: a week counts when either target reason paid it, and from the cutover
-- week on a week is judged only once its seven days have closed (week_start + 6 <= local_today - 2).
-- Weeks before that are judged as soon as they end, as before: their workouts paid at once.

create or replace function public.close_weeks(p_user uuid, p_rebuild boolean default false) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_now    date := public.local_week_start(p_user);
  v_closed date := public.local_today(p_user) - 8;
  v_cut    date := public.week_start_of(public.training_checkin_since());
  v_s      public.streaks%rowtype;
  v_week   date;
begin
  if not exists (select 1 from public.profiles where id = p_user) then return; end if;
  insert into public.streaks (user_id, kind) values (p_user, 'training_week') on conflict do nothing;
  select * into v_s from public.streaks where user_id = p_user and kind = 'training_week' for update;
  if p_rebuild then
    v_s.current := 0;
    v_s.shields := 0;
    v_s.last_period := null;
  end if;

  if v_s.last_period is null then
    select least(
      (select public.week_start_of(min(occurred_on)) from public.activity_events where user_id = p_user),
      (select public.week_start_of((created_at at time zone timezone)::date) from public.profiles where id = p_user)
    ) into v_week;
  else
    v_week := v_s.last_period + 7;
  end if;

  while v_week is not null and v_week < v_now and (v_week < v_cut or v_week <= v_closed) loop
    if exists (select 1 from public.xp_ledger
                where user_id = p_user and reason in ('week_target', 'training_week_target')
                  and week_start = v_week) then
      v_s.current := v_s.current + 1;
      v_s.best := greatest(v_s.best, v_s.current);
      if v_s.current % 4 = 0 then v_s.shields := least(2, v_s.shields + 1); end if;
    elsif v_s.current > 0 and v_s.shields > 0 then
      v_s.shields := v_s.shields - 1;
    else
      v_s.current := 0;
    end if;
    v_s.last_period := v_week;
    v_week := v_week + 7;
  end loop;

  update public.streaks
     set current = v_s.current, best = v_s.best, shields = v_s.shields, last_period = v_s.last_period
   where user_id = p_user and kind = 'training_week';
end $$;

revoke all on function public.close_weeks(uuid, boolean) from public, anon, authenticated;

-- XP per event --------------------------------------------------------------------------------------
-- 0010's nutrition branch unchanged. Strength:
--   workout_completed  from the cutover on: no day XP (the check-in pays the day). Before it: the
--                      old branch, unless the day already closed paid by a check-in; a closed day
--                      it lands on becomes legacy.
--   training_day       10 (training_logged, once a day), then round(600/T) up to the T-th day
--                      (training_day, the T-th takes the rest) with +150 (training_week_target),
--                      or 25 (training_day_extra, 2 a week)
--   training_detailed  30, 3 a week
-- Days and extras count old and new reasons together, so a cutover week pays 600 + 150 once.

create or replace function public.award_xp() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_week   date := public.week_start_of(new.occurred_on);
  v_target smallint;
  v_count  integer;
begin
  -- One award at a time per user: the counts below decide the amount.
  perform pg_advisory_xact_lock(hashtextextended('xp:' || new.user_id::text, 0));

  if new.pillar = 'nutrition' then
    if new.kind = 'day_on_target' then
      v_target := public.week_target_for(new.user_id, v_week, 'nutrition');
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'nutrition_day';
      if v_count < v_target then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', public.session_xp(v_target, v_count + 1), 'nutrition_day', new.id, v_week);
        if v_count + 1 = v_target then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'nutrition', 150, 'nutrition_week_target', new.id, v_week);
        end if;
      else
        select count(*) into v_count from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason = 'nutrition_day_extra';
        if v_count < 2 then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'nutrition', 25, 'nutrition_day_extra', new.id, v_week);
        end if;
      end if;
    elsif new.kind = 'macros_balanced' then
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'nutrition_balanced';
      if v_count < 3 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', 30, 'nutrition_balanced', new.id, v_week);
      end if;
    elsif new.kind = 'day_logged' then
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'nutrition_logged' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', 10, 'nutrition_logged', new.id, v_week);
      end if;
    end if;
    perform public.evaluate_achievements(new.user_id);
    return null;
  end if;

  if new.pillar <> 'strength' then return null; end if;

  if new.kind in ('workout_completed', 'training_day') then
    if new.kind = 'workout_completed' then
      -- From the cutover on, the day is paid by its check-in when it closes.
      if new.occurred_on >= public.training_checkin_since() then
        perform public.evaluate_achievements(new.user_id);
        return null;
      end if;
      -- A day before the cutover already paid by its check-in pays nothing again.
      if exists (select 1 from public.training_days
                  where user_id = new.user_id and day = new.occurred_on and checked and not legacy) then
        perform public.evaluate_achievements(new.user_id);
        return null;
      end if;
      update public.training_days set checked = true, legacy = true
       where user_id = new.user_id and day = new.occurred_on;
    else
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'training_logged' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 10, 'training_logged', new.id, v_week);
      end if;
    end if;

    v_target := public.week_target_for(new.user_id, v_week, 'strength');
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason in ('workout', 'training_day');
    if v_count < v_target then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', public.session_xp(v_target, v_count + 1),
              case when new.kind = 'training_day' then 'training_day' else 'workout' end, new.id, v_week);
      if v_count + 1 = v_target and not exists (
        select 1 from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason in ('week_target', 'training_week_target')
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 150,
                case when new.kind = 'training_day' then 'training_week_target' else 'week_target' end,
                new.id, v_week);
        -- A goal met in a week already judged changes that week's verdict: replay the streak.
        if exists (select 1 from public.streaks
                    where user_id = new.user_id and kind = 'training_week' and last_period >= v_week) then
          perform public.close_weeks(new.user_id, true);
        end if;
      end if;
    else
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason in ('workout_extra', 'training_day_extra');
      if v_count < 2 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 25,
                case when new.kind = 'training_day' then 'training_day_extra' else 'workout_extra' end,
                new.id, v_week);
      end if;
    end if;
  elsif new.kind = 'training_detailed' then
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason = 'training_detailed';
    if v_count < 3 then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 30, 'training_detailed', new.id, v_week);
    end if;
  elsif new.kind = 'pr' then
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason = 'pr';
    if v_count < 3 then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 30, 'pr', new.id, v_week);
    end if;
  elsif new.kind = 'weight_logged' then
    if not exists (
      select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
       where l.user_id = new.user_id and l.reason = 'weight' and e.occurred_on = new.occurred_on
    ) then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 10, 'weight', new.id, v_week);
    end if;
  end if;
  perform public.evaluate_achievements(new.user_id);
  return null;
end $$;

revoke all on function public.award_xp() from public, anon, authenticated;

-- Closing days ---------------------------------------------------------------------------------------
-- Every day without a row from the person's first check-in or legacy workout up to
-- local_today - 2, one row each (unchecked days included). Runs as the owner: the server-only
-- events pass RLS and the 14-day window, and award_xp pays them. Ends judging the streak weeks.

create function public.close_training_days(p_user uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_cut      date;
  v_first    date;
  v_last     date;
  v_day      date;
  v_checked  boolean;
  v_detailed boolean;
  v_legacy   boolean;
  v_ref      text;
  n          integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('xp:' || p_user::text, 0));
  v_cut := public.training_checkin_since();
  v_last := public.local_today(p_user) - 2;
  select least(
    (select min(day) from public.checkins where user_id = p_user),
    (select min(occurred_on) from public.activity_events
      where user_id = p_user and kind = 'workout_completed' and occurred_on < v_cut)
  ) into v_first;
  if v_first is null or v_first > v_last then return 0; end if;

  for v_day in
    select d::date from generate_series(v_first, v_last, interval '1 day') d
     where not exists (select 1 from public.training_days x where x.user_id = p_user and x.day = d::date)
     order by 1
  loop
    select count(*) > 0,
           coalesce(bool_or(jsonb_typeof(detail -> 'entries') = 'array'
                            and jsonb_array_length(detail -> 'entries') > 0), false)
      into v_checked, v_detailed
      from public.checkins where user_id = p_user and day = v_day;
    v_legacy := v_day < v_cut and exists (
      select 1 from public.activity_events
       where user_id = p_user and kind = 'workout_completed' and occurred_on = v_day);

    insert into public.training_days (user_id, day, checked, detailed, legacy)
    values (p_user, v_day, v_checked or v_legacy, v_detailed, v_legacy);

    if v_checked and not v_legacy then
      v_ref := 'training:' || to_char(v_day, 'YYYY-MM-DD');
      insert into public.activity_events (user_id, pillar, kind, occurred_on, source_ref)
      values (p_user, 'strength', 'training_day', v_day, v_ref) on conflict do nothing;
      if v_detailed then
        insert into public.activity_events (user_id, pillar, kind, occurred_on, source_ref)
        values (p_user, 'strength', 'training_detailed', v_day, v_ref) on conflict do nothing;
      end if;
    end if;
    n := n + 1;
  end loop;

  perform public.close_weeks(p_user);
  return n;
end $$;

revoke all on function public.close_training_days(uuid) from public, anon, authenticated;

-- Daily safety net (scheduled at the end) --------------------------------------------------------
-- Everyone with a check-in or a legacy workout on a due day that has no row yet. Returns how many
-- people it went through.

create function public.close_all_training_days() returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_cut date := public.training_checkin_since();
  r     record;
  n     integer := 0;
begin
  for r in
    select u.user_id from (
      select c.user_id, c.day from public.checkins c
      union
      select e.user_id, e.occurred_on from public.activity_events e
       where e.kind = 'workout_completed' and e.occurred_on < v_cut
    ) u
     where not exists (select 1 from public.training_days t where t.user_id = u.user_id and t.day = u.day)
     group by u.user_id
    having min(u.day) <= public.local_today(u.user_id) - 2
  loop
    perform public.close_training_days(r.user_id);
    n := n + 1;
  end loop;
  return n;
end $$;

revoke all on function public.close_all_training_days() from public, anon, authenticated;

-- Achievement metrics ---------------------------------------------------------------------------------
-- 0011's, with workouts = workouts before the cutover (as before) + checked training days that are
-- not legacy; week_targets counts both target reasons.

create or replace function public.achievement_stats(p_user uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'workouts', (select count(*) from public.activity_events
                  where user_id = p_user and kind = 'workout_completed'
                    and occurred_on < public.training_checkin_since())
              + (select count(*) from public.training_days where user_id = p_user and checked and not legacy),
    'prs', (select count(*) from public.activity_events where user_id = p_user and kind = 'pr'),
    'week_targets', (select count(*) from public.xp_ledger
                      where user_id = p_user and reason in ('week_target', 'training_week_target')),
    'best_streak', coalesce((select best from public.streaks where user_id = p_user and kind = 'training_week'), 0),
    -- Longest run of consecutive weigh-in days (gaps and islands).
    'weigh_in_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select d - (row_number() over (order by d))::int as grp
            from (select distinct occurred_on as d from public.activity_events
                   where user_id = p_user and kind = 'weight_logged') days
        ) runs group by grp
      ) lengths), 0),
    -- Live sessions only: the app sends the local start hour for those, never for backfills.
    'early_workouts', (select count(*) from public.activity_events
                        where user_id = p_user and kind = 'workout_completed'
                          and jsonb_typeof(payload -> 'hour') = 'number' and (payload ->> 'hour')::numeric < 7),
    'friends', (select count(*) from public.friendships where p_user in (user_a, user_b)),
    'challenges_won', (select count(*) from public.challenge_members where user_id = p_user and won),
    'nutrition_logged_days', (select count(*) from public.nutrition_days
                               where user_id = p_user and not imported and logged),
    'nutrition_on_target_days', (select count(*) from public.nutrition_days
                                  where user_id = p_user and not imported and on_target),
    'nutrition_week_targets', (select count(*) from public.xp_ledger
                                where user_id = p_user and reason = 'nutrition_week_target'),
    'nutrition_best_streak', coalesce((select best from public.streaks
                                        where user_id = p_user and kind = 'nutrition_week'), 0),
    -- Longest run of consecutive closed days with protein at or above the target in force.
    'protein_best_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select day - (row_number() over (order by day))::int as grp
            from public.nutrition_days
           where user_id = p_user and not imported
             and protein_g >= (target ->> 'protein_g')::numeric
        ) runs group by grp
      ) lengths), 0)
  )
$$;

revoke all on function public.achievement_stats(uuid) from public, anon, authenticated;

-- Challenges: weeks_on_target ---------------------------------------------------------------------
-- 0015's, with a week met by either target reason. workouts_count moves to training days in 0020.

create or replace function public.challenge_progress(p_challenge uuid, p_user uuid) returns numeric
language plpgsql stable security definer set search_path = public as $$
declare
  c public.challenges%rowtype;
  v numeric;
begin
  select * into c from public.challenges where id = p_challenge;
  if not found then return null; end if;
  if c.template = 'workouts_count' then
    select count(*) into v from public.activity_events
     where user_id = p_user and kind = 'workout_completed' and occurred_on between c.starts_on and c.ends_on;
  elsif c.template = 'weeks_on_target' then
    select count(*) into v from public.xp_ledger
     where user_id = p_user and reason in ('week_target', 'training_week_target')
       and week_start between public.week_start_of(c.starts_on) and c.ends_on;
  elsif c.template = 'nutrition_days_on_target' then
    select count(*) into v from public.nutrition_days
     where user_id = p_user and on_target and not imported and day between c.starts_on and c.ends_on
       and public.nutrition_active_on(p_user, day);
  else
    select coalesce(sum(least(greatest((payload ->> 'vol')::numeric, 0), 100000)), 0) into v
      from public.activity_events
     where user_id = p_user and kind = 'workout_completed' and occurred_on between c.starts_on and c.ends_on
       and jsonb_typeof(payload -> 'vol') = 'number';
    v := round(v * (case when (select unit from public.profiles where id = p_user) = 'lb'
                         then 0.45359237 else 1 end) / 1000, 1);
  end if;
  return v;
end $$;

-- Public card -----------------------------------------------------------------------------------------
-- 0012's, with the week counting training days with the old sessions: workouts (days paid up to
-- T), extras and target_hit read both reasons. Only counts: nothing of a check-in leaves here.

create or replace function public.progress_card(p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_week   date := public.local_week_start(p_user);
  v_total  bigint := public.total_xp(p_user);
  v_target smallint;
  v_streak public.streaks%rowtype;
  v_count  jsonb;
  v_split  jsonb;
begin
  v_target := coalesce(
    (select target from public.weekly_targets where user_id = p_user and pillar = 'strength' and week_start = v_week),
    (select days_per_week from public.profiles where id = p_user), 3);
  select * into v_streak from public.streaks where user_id = p_user and kind = 'training_week';
  select jsonb_build_object(
           'workouts', count(*) filter (where reason in ('workout', 'training_day')),
           'extras', count(*) filter (where reason in ('workout_extra', 'training_day_extra')),
           'prs', count(*) filter (where reason = 'pr'),
           'target_hit', count(*) filter (where reason in ('week_target', 'training_week_target')) > 0),
         jsonb_build_object(
           'strength', coalesce(sum(amount) filter (where pillar = 'strength'), 0),
           'nutrition', coalesce(sum(amount) filter (where pillar = 'nutrition'), 0),
           'bonus', coalesce(sum(amount) filter (where pillar is null), 0))
    into v_count, v_split
    from public.xp_ledger where user_id = p_user and week_start = v_week;
  return jsonb_build_object(
    'total_xp', v_total,
    'level', public.level_json(v_total),
    'pillars', (
      select coalesce(jsonb_object_agg(p.name, public.level_json(p.xp) || jsonb_build_object('xp', p.xp)), '{}'::jsonb)
        from (select e::text as name,
                     coalesce((select sum(amount) from public.xp_ledger where user_id = p_user and pillar = e), 0)::bigint as xp
                from unnest(enum_range(null::public.pillar)) e) p
       where p.name = 'strength' or p.xp > 0),
    'week', jsonb_build_object(
              'start', v_week, 'xp', public.week_xp(p_user, v_week),
              'max', 960 * (1 + public.nutrition_week_active(p_user, v_week)::int),
              'target', v_target, 'pillars', v_split) || v_count,
    'streak', jsonb_build_object('current', coalesce(v_streak.current, 0), 'best', coalesce(v_streak.best, 0),
                                 'shields', coalesce(v_streak.shields, 0)),
    'achievements', coalesce((
      select jsonb_agg(jsonb_build_object('code', u.code, 'unlocked_at', u.unlocked_at) order by u.unlocked_at, u.code)
        from public.user_achievements u join public.achievement_catalog c on c.code = u.code
       where u.user_id = p_user and not c.private), '[]'::jsonb)
  );
end $$;

revoke all on function public.progress_card(uuid) from public, anon, authenticated;

-- The owner's extras ----------------------------------------------------------------------------------
-- 0012's, plus the training block once the person ever posted a check-in (for the "day
-- confirmed" celebration):
--   training.confirms_on  the day today closes (today + 2)
--   training.last_closed  the last closed day with a check-in that paid, whether it was detailed,
--                         and the XP its events paid

create or replace function public.my_progress_extras(p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_today  date := public.local_today(p_user);
  v_week   date := public.week_start_of(v_today);
  v_lw     date := public.week_start_of(v_today - 8);
  v_first  date;
  v_streak public.streaks%rowtype;
  v_day    public.nutrition_days%rowtype;
  v_tday   public.training_days%rowtype;
  v_nut    jsonb;
  v_train  jsonb;
begin
  select public.week_start_of(min(started_on)) into v_first
    from public.nutrition_periods where user_id = p_user;
  if v_first is not null then
    select * into v_streak from public.streaks where user_id = p_user and kind = 'nutrition_week';
    select * into v_day from public.nutrition_days
     where user_id = p_user and not imported order by day desc limit 1;
    v_nut := jsonb_build_object(
      'target', coalesce(
        (select target from public.weekly_targets where user_id = p_user and pillar = 'nutrition' and week_start = v_week),
        (select nutrition_days_per_week from public.profiles where id = p_user), 5),
      'on_target', (select count(*) from public.nutrition_days
                     where user_id = p_user and not imported and on_target and day between v_week and v_week + 6),
      'logged', (select count(*) from public.nutrition_days
                  where user_id = p_user and not imported and logged and day between v_week and v_week + 6),
      'streak', jsonb_build_object('current', coalesce(v_streak.current, 0), 'best', coalesce(v_streak.best, 0),
                                   'shields', coalesce(v_streak.shields, 0)),
      'confirms_on', v_today + 2,
      'last_closed', case when v_day.day is null then null else jsonb_build_object(
        'day', v_day.day, 'logged', v_day.logged, 'on_target', v_day.on_target, 'balanced', v_day.balanced,
        'xp', coalesce((
          select sum(l.amount) from public.xp_ledger l join public.activity_events e on e.id = l.event_id
           where l.user_id = p_user and e.user_id = p_user and e.pillar = 'nutrition'
             and e.occurred_on = v_day.day), 0)) end,
      'last_week', case when v_lw < v_first then null else jsonb_build_object(
        'start', v_lw,
        'target_hit', exists (select 1 from public.xp_ledger
                               where user_id = p_user and reason = 'nutrition_week_target' and week_start = v_lw)) end);
  end if;

  if exists (select 1 from public.checkins where user_id = p_user) then
    select * into v_tday from public.training_days
     where user_id = p_user and checked and not legacy order by day desc limit 1;
    v_train := jsonb_build_object(
      'confirms_on', v_today + 2,
      'last_closed', case when v_tday.day is null then null else jsonb_build_object(
        'day', v_tday.day, 'detailed', v_tday.detailed,
        'xp', coalesce((
          select sum(l.amount) from public.xp_ledger l join public.activity_events e on e.id = l.event_id
           where l.user_id = p_user and e.user_id = p_user
             and e.kind in ('training_day', 'training_detailed') and e.occurred_on = v_tday.day), 0)) end);
  end if;

  return jsonb_build_object(
    'achievements', coalesce((
      select jsonb_agg(jsonb_build_object('code', code, 'unlocked_at', unlocked_at) order by unlocked_at, code)
        from public.user_achievements where user_id = p_user), '[]'::jsonb),
    'radar', jsonb_build_object(
      'strength', jsonb_build_object('current', public.pillar_consistency(p_user, 'strength', 0),
                                     'previous', public.pillar_consistency(p_user, 'strength', 1)),
      'nutrition', jsonb_build_object('current', public.pillar_consistency(p_user, 'nutrition', 0),
                                      'previous', public.pillar_consistency(p_user, 'nutrition', 1))))
    || case when v_nut is null then '{}'::jsonb else jsonb_build_object('nutrition', v_nut) end
    || case when v_train is null then '{}'::jsonb else jsonb_build_object('training', v_train) end;
end $$;

revoke all on function public.my_progress_extras(uuid) from public, anon, authenticated;

-- The owner's answer ----------------------------------------------------------------------------------
-- 0012's, closing pending training days (which judges the strength weeks) before the rest.

create or replace function public.get_my_progress() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid   uuid := auth.uid();
  v_today date;
  v_card  jsonb;
begin
  if v_uid is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if not exists (select 1 from public.profiles where id = v_uid) then
    raise exception 'no_profile' using errcode = 'P0002';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('xp:' || v_uid::text, 0));
  v_today := public.local_today(v_uid);
  perform public.week_target_for(v_uid, public.week_start_of(v_today), 'strength');
  perform public.week_target_for(v_uid, public.week_start_of(v_today), 'nutrition');
  perform public.close_training_days(v_uid);
  perform public.close_weeks(v_uid);
  perform public.close_nutrition_days(v_uid);
  perform public.evaluate_achievements(v_uid);
  v_card := public.progress_card(v_uid);
  return v_card || public.my_progress_extras(v_uid) || jsonb_build_object(
    'today', v_today,
    'stats', public.achievement_stats(v_uid) || jsonb_build_object('level', (v_card -> 'level' ->> 'level')::int),
    'week', (v_card -> 'week') || jsonb_build_object('weighed_today', exists (
      select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
       where l.user_id = v_uid and l.reason = 'weight' and e.occurred_on = v_today)));
end $$;

revoke all on function public.get_my_progress() from public, anon;
grant execute on function public.get_my_progress() to authenticated;

-- Daily safety net: pays the days, the weekly streak and the badges of people who stay away. Only
-- where pg_cron exists (Supabase, once enabled; docs/SETUP.md §7); elsewhere, PGlite included, a
-- no-op. Runs before close-weeks (06:00) so the weeks it judges see the closed days.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron with schema pg_catalog;
    -- Same job name again updates the schedule instead of adding a second job.
    execute $cron$ select cron.schedule('close-training-days', '45 5 * * *', 'select public.close_all_training_days()') $cron$;
  end if;
exception when others then
  raise notice 'close-training-days not scheduled: %', sqlerrm;
end $$;

-- ===== 0020_checkin_feed.sql =====
-- Phase 1c, the check-in feed and the training days challenge (spec 4.1, 4.5, 6.2), plus the fixes
-- from the review of Tasks 1 to 3. 0017 to 0020 ship together.
--
--   get_checkin_feed     friends' posts for friends and all of one's own, newest first, 20 a page;
--                        workouts from before the cutover stay as the old items. get_feed (0004)
--                        stays as it was for the client still in use while this deploys.
--   get_challenge_feed   the members' posts in the challenge period; a post the caller may not see
--                        is a bare "private check-in" (it still counts on the board).
--   checkin_days         new template: closed days with a check-in. workouts_count now counts the
--                        same days (legacy workout days included).
--   challenge_grace      2 for every template paid by closed training days, and close_challenge
--                        closes the members' pending training days first (review, Important 1).
--   award_xp             from the cutover pr and weight_logged pay no XP, so the Treino week stays
--                        at 960 (spec 5.1; review, Minor 1). The events and the badges stay.
--   achievement_stats    a legacy workout on a day its check-in paid is not counted again (Minor 2).
--   checkins_guard       refuses a closed day and locks per person and day (Minor 4 and 5).
--   notify_checkin_social  no new reaction notice while one from the same person is unread (Minor 6).
--
-- Every redefined body is its latest one (challenge_progress, award_xp, achievement_stats: 0019;
-- create_challenge, close_challenge: 0015; checkins_guard: 0017; notify_checkin_social: 0018) with
-- only the parts above changed. No signature changes.

-- Training days challenge ------------------------------------------------------------------------

alter table public.challenges drop constraint challenges_template_check;
alter table public.challenges add constraint challenges_template_check
  check (template in ('workouts_count', 'weeks_on_target', 'volume_total', 'nutrition_days_on_target',
                      'checkin_days'));

-- checkin_days and workouts_count: closed days with a check-in in the period (a legacy day, before
-- the cutover with a workout, is checked too). Several posts on a day are one day.

create or replace function public.challenge_progress(p_challenge uuid, p_user uuid) returns numeric
language plpgsql stable security definer set search_path = public as $$
declare
  c public.challenges%rowtype;
  v numeric;
begin
  select * into c from public.challenges where id = p_challenge;
  if not found then return null; end if;
  if c.template in ('workouts_count', 'checkin_days') then
    select count(*) into v from public.training_days
     where user_id = p_user and checked and day between c.starts_on and c.ends_on;
  elsif c.template = 'weeks_on_target' then
    select count(*) into v from public.xp_ledger
     where user_id = p_user and reason in ('week_target', 'training_week_target')
       and week_start between public.week_start_of(c.starts_on) and c.ends_on;
  elsif c.template = 'nutrition_days_on_target' then
    select count(*) into v from public.nutrition_days
     where user_id = p_user and on_target and not imported and day between c.starts_on and c.ends_on
       and public.nutrition_active_on(p_user, day);
  else
    select coalesce(sum(least(greatest((payload ->> 'vol')::numeric, 0), 100000)), 0) into v
      from public.activity_events
     where user_id = p_user and kind = 'workout_completed' and occurred_on between c.starts_on and c.ends_on
       and jsonb_typeof(payload -> 'vol') = 'number';
    v := round(v * (case when (select unit from public.profiles where id = p_user) = 'lb'
                         then 0.45359237 else 1 end) / 1000, 1);
  end if;
  return v;
end $$;

revoke all on function public.challenge_progress(uuid, uuid) from public, anon, authenticated;

-- checkin_days takes the rules of workouts_count: team or solo, 1 to 500 days
-- (supabase/tests/challenge-rules-parity.test.ts holds it to the client's workouts_count rules).
-- workouts_count is still accepted for clients that offer it.

create or replace function public.create_challenge(
  p_template text, p_title text, p_mode text, p_target numeric, p_starts_on date, p_ends_on date,
  p_invitees uuid[], p_share_volume boolean default false, p_share_nutrition boolean default false
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me     uuid := auth.uid();
  v_title  text := btrim(coalesce(p_title, ''));
  v_today  date;
  v_people uuid[];
  v_id     uuid;
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if not exists (select 1 from public.profiles where id = v_me) then
    raise exception 'no_profile' using errcode = 'P0002';
  end if;
  v_today := public.local_today(v_me);
  select coalesce(array_agg(distinct u), '{}') into v_people
    from unnest(coalesce(p_invitees, '{}'::uuid[])) u where u is not null and u <> v_me;

  -- Same rules as checkChallenge in src/features/social/templates.ts.
  if p_template is null
     or p_template not in ('workouts_count', 'weeks_on_target', 'volume_total', 'nutrition_days_on_target',
                           'checkin_days')
     or p_mode is null or p_mode not in ('team', 'solo')
     or (p_template = 'weeks_on_target' and p_mode <> 'solo')
     or char_length(v_title) not between 1 and 60
     or p_starts_on is null or p_ends_on is null
     or p_ends_on - p_starts_on not between 6 and 91
     or p_starts_on < v_today or p_starts_on > v_today + 30
     or p_target is null or p_target <> trunc(p_target) or p_target < 1
     or (p_template in ('workouts_count', 'checkin_days') and p_target > 500)
     or (p_template = 'volume_total' and p_target > 5000)
     or (p_template = 'weeks_on_target'
         and p_target > (public.week_start_of(p_ends_on) - public.week_start_of(p_starts_on)) / 7 + 1)
     or (p_template = 'nutrition_days_on_target'
         and p_target > (p_ends_on - p_starts_on + 1)
                        * (case when p_mode = 'team' then 1 + cardinality(v_people) else 1 end))
     or cardinality(v_people) not between 1 and 19 then
    raise exception 'invalid_challenge' using errcode = 'P0001';
  end if;
  if exists (select 1 from unnest(v_people) u where not public.are_friends(v_me, u)) then
    raise exception 'not_friends' using errcode = 'P0001';
  end if;
  if p_template = 'volume_total' and not coalesce(p_share_volume, false) then
    raise exception 'volume_opt_in_required' using errcode = 'P0001';
  end if;
  if p_template = 'nutrition_days_on_target' then
    if not (select nutrition_enabled from public.profiles where id = v_me) then
      raise exception 'nutrition_off' using errcode = 'P0001';
    end if;
    if not coalesce(p_share_nutrition, false) then
      raise exception 'nutrition_opt_in_required' using errcode = 'P0001';
    end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('challenge-create:' || v_me::text, 0));
  if (select count(*) from public.challenges where created_by = v_me and status = 'active') >= 10 then
    raise exception 'challenge_limit' using errcode = 'P0001';
  end if;

  insert into public.challenges (template, title, mode, target, starts_on, ends_on, created_by)
  values (p_template, v_title, p_mode, p_target, p_starts_on, p_ends_on, v_me)
  returning id into v_id;
  insert into public.challenge_members (challenge_id, user_id, invited_by, joined_at, share_volume, share_nutrition)
  values (v_id, v_me, null, public.app_now(), p_template = 'volume_total', p_template = 'nutrition_days_on_target');
  insert into public.challenge_members (challenge_id, user_id, invited_by)
  select v_id, u, v_me from unnest(v_people) u;
  return jsonb_build_object('id', v_id);
end $$;

revoke all on function
  public.create_challenge(text, text, text, numeric, date, date, uuid[], boolean, boolean)
  from public, anon;
grant execute on function
  public.create_challenge(text, text, text, numeric, date, date, uuid[], boolean, boolean)
  to authenticated;

-- A training day closes at the start of D+2, like a nutrition day, so every template it pays
-- waits two days past ends_on.

create or replace function public.challenge_grace(p_template text) returns integer
language sql immutable security definer set search_path = public as $$
  select case when p_template in ('nutrition_days_on_target', 'weeks_on_target', 'workouts_count', 'checkin_days')
              then 2 else 0 end
$$;
revoke all on function public.challenge_grace(text) from public, anon, authenticated;

-- As 0015, and for the training templates every participant's pending training days are closed
-- after the XP locks are taken (close_training_days takes the same lock again) and before final.

create or replace function public.close_challenge(p_challenge uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  c         public.challenges%rowtype;
  v_members uuid[];
  v_won     boolean;
  v_user    uuid;
  r         record;
begin
  perform pg_advisory_xact_lock(hashtextextended('challenge-close', 0));
  select * into c from public.challenges where id = p_challenge for update;
  if not found or c.status <> 'active'
     or public.challenge_today(c.created_by, c.timezone) <= c.ends_on + public.challenge_grace(c.template) then
    return false;
  end if;
  delete from public.challenge_members where challenge_id = p_challenge and joined_at is null;
  select coalesce(array_agg(user_id order by user_id), '{}') into v_members
    from public.challenge_members where challenge_id = p_challenge;
  if cardinality(v_members) < 2 then
    update public.challenges set status = 'cancelled', closed_at = public.app_now() where id = p_challenge;
    return true;
  end if;
  perform public.lock_users(v_members);
  if c.template = 'nutrition_days_on_target' then
    foreach v_user in array v_members loop
      perform public.close_nutrition_days(v_user);
    end loop;
  end if;
  if c.template in ('weeks_on_target', 'workouts_count', 'checkin_days') then
    foreach v_user in array v_members loop
      perform public.close_training_days(v_user);
    end loop;
  end if;
  update public.challenge_members
     set final = coalesce(public.challenge_progress(p_challenge, user_id), 0)
   where challenge_id = p_challenge;
  if c.mode = 'team' then
    select sum(final) >= c.target into v_won from public.challenge_members where challenge_id = p_challenge;
    update public.challenge_members set won = v_won where challenge_id = p_challenge;
  else
    update public.challenge_members set won = (final >= c.target) where challenge_id = p_challenge;
    select bool_or(won) into v_won from public.challenge_members where challenge_id = p_challenge;
  end if;
  update public.challenges
     set status = case when v_won then 'won' else 'lost' end, closed_at = public.app_now()
   where id = p_challenge;
  for r in select user_id from public.challenge_members
            where challenge_id = p_challenge and won order by user_id loop
    perform public.award_bonus_xp(r.user_id, 300, 'challenge:' || p_challenge::text);
    perform public.evaluate_achievements(r.user_id);
  end loop;
  return true;
end $$;

revoke all on function public.close_challenge(uuid) from public, anon, authenticated;

-- XP per event -------------------------------------------------------------------------------------
-- 0019's, with pr and weight_logged paying only before the cutover. From it on the events are
-- still kept (PR badges, the weigh-in run) and the week of the pillar is the 960 of spec 5.1:
-- 600 days + 150 target + 50 extras + 90 detail + 70 photo days.

create or replace function public.award_xp() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_week   date := public.week_start_of(new.occurred_on);
  v_target smallint;
  v_count  integer;
begin
  -- One award at a time per user: the counts below decide the amount.
  perform pg_advisory_xact_lock(hashtextextended('xp:' || new.user_id::text, 0));

  if new.pillar = 'nutrition' then
    if new.kind = 'day_on_target' then
      v_target := public.week_target_for(new.user_id, v_week, 'nutrition');
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'nutrition_day';
      if v_count < v_target then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', public.session_xp(v_target, v_count + 1), 'nutrition_day', new.id, v_week);
        if v_count + 1 = v_target then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'nutrition', 150, 'nutrition_week_target', new.id, v_week);
        end if;
      else
        select count(*) into v_count from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason = 'nutrition_day_extra';
        if v_count < 2 then
          insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
          values (new.user_id, 'nutrition', 25, 'nutrition_day_extra', new.id, v_week);
        end if;
      end if;
    elsif new.kind = 'macros_balanced' then
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason = 'nutrition_balanced';
      if v_count < 3 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', 30, 'nutrition_balanced', new.id, v_week);
      end if;
    elsif new.kind = 'day_logged' then
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'nutrition_logged' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'nutrition', 10, 'nutrition_logged', new.id, v_week);
      end if;
    end if;
    perform public.evaluate_achievements(new.user_id);
    return null;
  end if;

  if new.pillar <> 'strength' then return null; end if;

  if new.kind in ('workout_completed', 'training_day') then
    if new.kind = 'workout_completed' then
      -- From the cutover on, the day is paid by its check-in when it closes.
      if new.occurred_on >= public.training_checkin_since() then
        perform public.evaluate_achievements(new.user_id);
        return null;
      end if;
      -- A day before the cutover already paid by its check-in pays nothing again.
      if exists (select 1 from public.training_days
                  where user_id = new.user_id and day = new.occurred_on and checked and not legacy) then
        perform public.evaluate_achievements(new.user_id);
        return null;
      end if;
      update public.training_days set checked = true, legacy = true
       where user_id = new.user_id and day = new.occurred_on;
    else
      if not exists (
        select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
         where l.user_id = new.user_id and l.reason = 'training_logged' and e.occurred_on = new.occurred_on
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 10, 'training_logged', new.id, v_week);
      end if;
    end if;

    v_target := public.week_target_for(new.user_id, v_week, 'strength');
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason in ('workout', 'training_day');
    if v_count < v_target then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', public.session_xp(v_target, v_count + 1),
              case when new.kind = 'training_day' then 'training_day' else 'workout' end, new.id, v_week);
      if v_count + 1 = v_target and not exists (
        select 1 from public.xp_ledger
         where user_id = new.user_id and week_start = v_week and reason in ('week_target', 'training_week_target')
      ) then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 150,
                case when new.kind = 'training_day' then 'training_week_target' else 'week_target' end,
                new.id, v_week);
        -- A goal met in a week already judged changes that week's verdict: replay the streak.
        if exists (select 1 from public.streaks
                    where user_id = new.user_id and kind = 'training_week' and last_period >= v_week) then
          perform public.close_weeks(new.user_id, true);
        end if;
      end if;
    else
      select count(*) into v_count from public.xp_ledger
       where user_id = new.user_id and week_start = v_week and reason in ('workout_extra', 'training_day_extra');
      if v_count < 2 then
        insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
        values (new.user_id, 'strength', 25,
                case when new.kind = 'training_day' then 'training_day_extra' else 'workout_extra' end,
                new.id, v_week);
      end if;
    end if;
  elsif new.kind = 'training_detailed' then
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason = 'training_detailed';
    if v_count < 3 then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 30, 'training_detailed', new.id, v_week);
    end if;
  elsif new.kind = 'pr' and new.occurred_on < public.training_checkin_since() then
    select count(*) into v_count from public.xp_ledger
     where user_id = new.user_id and week_start = v_week and reason = 'pr';
    if v_count < 3 then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 30, 'pr', new.id, v_week);
    end if;
  elsif new.kind = 'weight_logged' and new.occurred_on < public.training_checkin_since() then
    if not exists (
      select 1 from public.xp_ledger l join public.activity_events e on e.id = l.event_id
       where l.user_id = new.user_id and l.reason = 'weight' and e.occurred_on = new.occurred_on
    ) then
      insert into public.xp_ledger (user_id, pillar, amount, reason, event_id, week_start)
      values (new.user_id, 'strength', 10, 'weight', new.id, v_week);
    end if;
  end if;
  perform public.evaluate_achievements(new.user_id);
  return null;
end $$;

revoke all on function public.award_xp() from public, anon, authenticated;

-- Achievement metrics -------------------------------------------------------------------------------
-- 0019's, with a workout from before the cutover counted only on a day its check-in did not pay.

create or replace function public.achievement_stats(p_user uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'workouts', (select count(*) from public.activity_events e
                  where e.user_id = p_user and e.kind = 'workout_completed'
                    and e.occurred_on < public.training_checkin_since()
                    and not exists (select 1 from public.training_days t
                                     where t.user_id = p_user and t.day = e.occurred_on
                                       and t.checked and not t.legacy))
              + (select count(*) from public.training_days where user_id = p_user and checked and not legacy),
    'prs', (select count(*) from public.activity_events where user_id = p_user and kind = 'pr'),
    'week_targets', (select count(*) from public.xp_ledger
                      where user_id = p_user and reason in ('week_target', 'training_week_target')),
    'best_streak', coalesce((select best from public.streaks where user_id = p_user and kind = 'training_week'), 0),
    -- Longest run of consecutive weigh-in days (gaps and islands).
    'weigh_in_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select d - (row_number() over (order by d))::int as grp
            from (select distinct occurred_on as d from public.activity_events
                   where user_id = p_user and kind = 'weight_logged') days
        ) runs group by grp
      ) lengths), 0),
    -- Live sessions only: the app sends the local start hour for those, never for backfills.
    'early_workouts', (select count(*) from public.activity_events
                        where user_id = p_user and kind = 'workout_completed'
                          and jsonb_typeof(payload -> 'hour') = 'number' and (payload ->> 'hour')::numeric < 7),
    'friends', (select count(*) from public.friendships where p_user in (user_a, user_b)),
    'challenges_won', (select count(*) from public.challenge_members where user_id = p_user and won),
    'nutrition_logged_days', (select count(*) from public.nutrition_days
                               where user_id = p_user and not imported and logged),
    'nutrition_on_target_days', (select count(*) from public.nutrition_days
                                  where user_id = p_user and not imported and on_target),
    'nutrition_week_targets', (select count(*) from public.xp_ledger
                                where user_id = p_user and reason = 'nutrition_week_target'),
    'nutrition_best_streak', coalesce((select best from public.streaks
                                        where user_id = p_user and kind = 'nutrition_week'), 0),
    -- Longest run of consecutive closed days with protein at or above the target in force.
    'protein_best_run', coalesce((
      select max(n) from (
        select count(*) as n from (
          select day - (row_number() over (order by day))::int as grp
            from public.nutrition_days
           where user_id = p_user and not imported
             and protein_g >= (target ->> 'protein_g')::numeric
        ) runs group by grp
      ) lengths), 0)
  )
$$;

revoke all on function public.achievement_stats(uuid) from public, anon, authenticated;

-- Check-in guard -------------------------------------------------------------------------------------
-- 0017's, refusing a day that already has its training_days row, and holding a lock per person and
-- day while counting the ten of the day.

create or replace function public.checkins_guard() returns trigger
language plpgsql security invoker set search_path = public as $$
declare
  v_today date;
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_today := public.my_local_today();
    if new.day not in (v_today - 1, v_today) then
      raise exception 'day_closed' using errcode = 'P0001';
    end if;
    -- A day already closed (yesterday after the time zone moved west, say) would never count it.
    if exists (select 1 from public.training_days where user_id = new.user_id and day = new.day) then
      raise exception 'day_closed' using errcode = 'P0001';
    end if;
    -- Two posts at once must not both pass the count.
    perform pg_advisory_xact_lock(
      hashtextextended('checkin-day:' || new.user_id::text || ':' || to_char(new.day, 'YYYY-MM-DD'), 0));
    if (select count(*) from public.checkins
         where user_id = new.user_id and day = new.day and id <> new.id) >= 10 then
      raise exception 'too_many_checkins' using errcode = 'P0001';
    end if;
    -- A post made offline keeps its earlier time; none is dated in the future to stay on top.
    new.created_at := least(coalesce(new.created_at, now()), now());
  else
    if new.id <> old.id or new.user_id <> old.user_id or new.day <> old.day
       or new.activity <> old.activity or new.photo_path <> old.photo_path then
      raise exception 'item_immutable' using errcode = 'P0001';
    end if;
    new.created_at := old.created_at;
  end if;

  new.updated_at := least(new.updated_at, now());
  if tg_op = 'UPDATE' and new.updated_at < old.updated_at then
    return null;
  end if;
  return new;
end $$;

revoke all on function public.checkins_guard() from public, anon, authenticated;

-- Reaction notices -------------------------------------------------------------------------------------
-- 0018's, with one unread reaction notice per person and post at most. Comments notify every time.

create or replace function public.notify_checkin_social() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_owner uuid;
begin
  select user_id into v_owner from public.checkins where id = new.checkin_id;
  if v_owner is not null and v_owner <> new.user_id then
    -- Reacting again (another emoji, or off and on) while the last notice is unread adds nothing.
    if tg_table_name = 'checkin_reactions' and exists (
      select 1 from public.social_notices
       where user_id = v_owner and actor_id = new.user_id and kind = 'reaction'
         and checkin_id = new.checkin_id and read_at is null) then
      return null;
    end if;
    insert into public.social_notices (user_id, actor_id, kind, checkin_id)
    values (v_owner, new.user_id,
            case when tg_table_name = 'checkin_reactions' then 'reaction' else 'comment' end,
            new.checkin_id);
  end if;
  return null;
end $$;

revoke all on function public.notify_checkin_social() from public, anon, authenticated;

-- Feed items -----------------------------------------------------------------------------------------
-- Built only for posts the caller may see. Never note, detail, routine or anything of the workout
-- beyond what is listed here.
--   key       'checkin:<id>' or 'workout:<id>'; with the time it orders the feed (byte order)
--   context   week_count: which training day of its week the post's day is (days with a check-in,
--             or a workout before the cutover, from Monday up to that day); streak: the owner's
--             current training_week streak

create function public.checkin_feed_item(p_id uuid, p_me uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'type', 'checkin',
    'key', 'checkin:' || c.id::text,
    'at', c.created_at,
    'day', c.day,
    'user', (select jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url)
               from public.profiles p where p.id = c.user_id),
    'activity', c.activity,
    'title', c.title,
    'caption', c.caption,
    'duration_min', c.duration_min,
    'visibility', c.visibility,
    'photo_path', c.photo_path,
    'context', jsonb_build_object(
      'week_count', (
        select count(distinct d) from (
          select k.day as d from public.checkins k
           where k.user_id = c.user_id and k.day between public.week_start_of(c.day) and c.day
          union all
          select e.occurred_on from public.activity_events e
           where e.user_id = c.user_id and e.kind = 'workout_completed'
             and e.occurred_on < public.training_checkin_since()
             and e.occurred_on between public.week_start_of(c.day) and c.day) x),
      'streak', coalesce((select s.current from public.streaks s
                           where s.user_id = c.user_id and s.kind = 'training_week'), 0)),
    'reactions', coalesce((
      select jsonb_agg(jsonb_build_object('emoji', g.emoji, 'count', g.n, 'mine', g.mine)
                       order by g.n desc, g.first_at, g.emoji)
        from (select r.emoji, count(*)::int as n, bool_or(r.user_id = p_me) as mine, min(r.created_at) as first_at
                from public.checkin_reactions r
               where r.checkin_id = c.id
               group by r.emoji) g), '[]'::jsonb),
    'comments_count', (select count(*)::int from public.checkin_comments m where m.checkin_id = c.id))
  from public.checkins c
  where c.id = p_id
$$;

-- A workout from before the cutover, as get_feed shows it: the set count and the PR exercise ids.
create function public.workout_feed_item(p_id bigint) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'type', 'workout',
    'key', 'workout:' || e.id::text,
    'at', e.created_at,
    'day', e.occurred_on,
    'user', (select jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url)
               from public.profiles p where p.id = e.user_id),
    'sets', case when jsonb_typeof(e.payload -> 'sets') = 'number'
                 then least(greatest((e.payload ->> 'sets')::numeric, 0), 999)::int end,
    'prs', coalesce((
      select jsonb_agg(left(pr.payload ->> 'ex', 40) order by pr.id)
        from public.activity_events pr
       where pr.user_id = e.user_id and pr.kind = 'pr'
         and jsonb_typeof(pr.payload -> 'ex') = 'string'
         and left(pr.source_ref, char_length(e.source_ref) + 1) = e.source_ref || ':'), '[]'::jsonb))
  from public.activity_events e
  where e.id = p_id
$$;

revoke all on function public.checkin_feed_item(uuid, uuid), public.workout_feed_item(bigint)
  from public, anon, authenticated;

-- The feed -------------------------------------------------------------------------------------------
-- Newest first by (at, key); a page ends at the 20th item and next carries its at and key, so a
-- post that arrives meanwhile never repeats or hides one. Without a key, p_before alone means
-- strictly earlier. Hidden posts are left out for whoever hid them. Opening the feed closes the
-- caller's pending training days (spec 5.2), as get_my_progress does.

create function public.get_checkin_feed(p_before timestamptz default null, p_before_key text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me    uuid := auth.uid();
  v_cut   date;
  v_items jsonb;
  v_n     integer;
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  perform public.close_training_days(v_me);
  v_cut := public.training_checkin_since();

  with page as (
    select * from (
      (select ('checkin:' || c.id::text) collate "C" as key, c.created_at as at, c.id as checkin_id,
              null::bigint as event_id
         from public.checkins c
        where (c.user_id = v_me
               or (c.visibility = 'friends' and c.user_id in (select public.friend_ids(v_me))))
          and not exists (select 1 from public.hidden_checkins h where h.user_id = v_me and h.checkin_id = c.id)
          and (p_before is null or c.created_at < p_before
               or (c.created_at = p_before
                   and ('checkin:' || c.id::text) collate "C" < coalesce(p_before_key, '') collate "C"))
        order by c.created_at desc, ('checkin:' || c.id::text) collate "C" desc
        limit 20)
      union all
      (select ('workout:' || e.id::text) collate "C", e.created_at, null::uuid, e.id
         from public.activity_events e
         join public.profiles p on p.id = e.user_id
        where e.kind = 'workout_completed'
          and e.occurred_on < v_cut
          and p.share_activity
          and e.user_id in (select public.friend_ids(v_me))
          and (p_before is null or e.created_at < p_before
               or (e.created_at = p_before
                   and ('workout:' || e.id::text) collate "C" < coalesce(p_before_key, '') collate "C"))
        order by e.created_at desc, ('workout:' || e.id::text) collate "C" desc
        limit 20)
    ) u
    order by u.at desc, u.key collate "C" desc
    limit 20
  )
  select coalesce(jsonb_agg(case when checkin_id is not null then public.checkin_feed_item(checkin_id, v_me)
                                 else public.workout_feed_item(event_id) end
                            order by at desc, key collate "C" desc), '[]'::jsonb),
         count(*)
    into v_items, v_n
    from page;

  return jsonb_build_object(
    'items', v_items,
    'next', case when v_n = 20 then
      jsonb_build_object('before', v_items -> 19 -> 'at', 'before_key', v_items -> 19 ->> 'key') end);
end $$;

-- A challenge's feed: posts of the people who joined, on the days of the period, newest first,
-- paged like the feed. One the caller may see (their own, or a friend's for friends) comes whole
-- with private: false; any other one only as { type, key, at, day, user, private: true }: no photo,
-- title, caption or activity. Members only (invited ones included); anyone else gets
-- challenge_not_found.

create function public.get_challenge_feed(p_id uuid, p_before timestamptz default null,
                                          p_before_key text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_me    uuid := auth.uid();
  v_c     public.challenges%rowtype;
  v_items jsonb;
  v_n     integer;
begin
  if v_me is null then raise exception 'not_signed_in' using errcode = '28000'; end if;
  if not exists (select 1 from public.challenge_members where challenge_id = p_id and user_id = v_me) then
    raise exception 'challenge_not_found' using errcode = 'P0002';
  end if;
  select * into v_c from public.challenges where id = p_id;

  with page as (
    select c.id, c.user_id, c.day, c.created_at as at, ('checkin:' || c.id::text) collate "C" as key
      from public.checkins c
      join public.challenge_members m
        on m.challenge_id = p_id and m.user_id = c.user_id and m.joined_at is not null
     where c.day between v_c.starts_on and v_c.ends_on
       and not exists (select 1 from public.hidden_checkins h where h.user_id = v_me and h.checkin_id = c.id)
       and (p_before is null or c.created_at < p_before
            or (c.created_at = p_before
                and ('checkin:' || c.id::text) collate "C" < coalesce(p_before_key, '') collate "C"))
     order by c.created_at desc, ('checkin:' || c.id::text) collate "C" desc
     limit 20
  )
  select coalesce(jsonb_agg(
           case when public.can_see_checkin(id)
                then public.checkin_feed_item(id, v_me) || jsonb_build_object('private', false)
                else jsonb_build_object(
                       'type', 'checkin', 'key', key, 'at', at, 'day', day, 'private', true,
                       'user', (select jsonb_build_object('id', p.id, 'name', p.display_name, 'avatar_url', p.avatar_url)
                                  from public.profiles p where p.id = page.user_id)) end
           order by at desc, key collate "C" desc), '[]'::jsonb),
         count(*)
    into v_items, v_n
    from page;

  return jsonb_build_object(
    'items', v_items,
    'next', case when v_n = 20 then
      jsonb_build_object('before', v_items -> 19 -> 'at', 'before_key', v_items -> 19 ->> 'key') end);
end $$;

revoke all on function public.get_checkin_feed(timestamptz, text),
  public.get_challenge_feed(uuid, timestamptz, text) from public, anon;
grant execute on function public.get_checkin_feed(timestamptz, text),
  public.get_challenge_feed(uuid, timestamptz, text) to authenticated;

-- Pillar radar --------------------------------------------------------------------------------------
-- 0012's, with the Treino (strength) weeks closing like the nutrition ones: a week is closed once its
-- Sunday closed at D+2 (week_start + 6 <= local_today - 2), so on Monday last week is not in yet.
-- Training days pay when they close, so a week judged earlier would miss its weekend. The active
-- weeks and the nutrition branch are unchanged.

create or replace function public.pillar_consistency(p_user uuid, p_pillar public.pillar, p_offset int) returns numeric
language plpgsql stable security definer set search_path = public as $$
declare
  v_last  date;
  v_first date;
  v_weeks date[];
  v_xp    bigint;
begin
  if p_pillar = 'strength' then
    v_last := public.week_start_of(public.local_today(p_user) - 8);
    select least(
      (select public.week_start_of(min(occurred_on)) from public.activity_events where user_id = p_user),
      (select public.week_start_of((created_at at time zone coalesce(timezone, 'America/Sao_Paulo'))::date)
         from public.profiles where id = p_user)
    ) into v_first;
  elsif p_pillar = 'nutrition' then
    v_last := public.week_start_of(public.local_today(p_user) - 8);
  else
    return null;
  end if;
  v_last := v_last - 28 * p_offset;

  select array_agg(w::date) into v_weeks
    from generate_series(v_last - 21, v_last, interval '7 days') w
   where case when p_pillar = 'strength' then w::date >= v_first
              else public.nutrition_week_active(p_user, w::date) end;
  if v_weeks is null then return null; end if;

  select coalesce(sum(amount), 0) into v_xp from public.xp_ledger
   where user_id = p_user and pillar = p_pillar and week_start = any(v_weeks);
  return least(1, round(v_xp::numeric / (960 * cardinality(v_weeks)), 4));
end $$;

revoke all on function public.pillar_consistency(uuid, public.pillar, int) from public, anon, authenticated;
